//! `CompilerMSL`: decompiles SPIR-V to Metal Shading Language.
//!
//! CompilerMSL's overrides of CompilerGLSL's virtual methods are the
//! `msl_*` targets of the dispatchers in the GLSL backend; its own
//! methods that share a name with one of CompilerGLSL's (which C++ hides)
//! are prefixed `msl_` as well.

use std::collections::{BTreeMap, BTreeSet, HashMap, HashSet};
use std::rc::Rc;

use super::common::*;
use super::cross::*;
use super::glsl::*;
use super::spirv::*;
use super::std_hash::StdHashMap;

// Indicates the format of a shader interface variable. Currently limited to specifying
// if the input is an 8-bit unsigned integer, 16-bit unsigned integer, or
// some other format.
pub type MSLShaderVariableFormat = u32;
pub const MSL_SHADER_VARIABLE_FORMAT_OTHER: MSLShaderVariableFormat = 0;
pub const MSL_SHADER_VARIABLE_FORMAT_UINT8: MSLShaderVariableFormat = 1;
pub const MSL_SHADER_VARIABLE_FORMAT_UINT16: MSLShaderVariableFormat = 2;
pub const MSL_SHADER_VARIABLE_FORMAT_ANY16: MSLShaderVariableFormat = 3;
pub const MSL_SHADER_VARIABLE_FORMAT_ANY32: MSLShaderVariableFormat = 4;

// Indicates the rate at which a variable changes value, one of: per-vertex,
// per-primitive, or per-patch.
pub type MSLShaderVariableRate = u32;
pub const MSL_SHADER_VARIABLE_RATE_PER_VERTEX: MSLShaderVariableRate = 0;
pub const MSL_SHADER_VARIABLE_RATE_PER_PRIMITIVE: MSLShaderVariableRate = 1;
pub const MSL_SHADER_VARIABLE_RATE_PER_PATCH: MSLShaderVariableRate = 2;

/// `MSLShaderInterfaceVariable`: defines MSL characteristics of a shader
/// interface variable at a particular location.
// After compilation, it is possible to query whether or not this location was used.
// If vecsize is nonzero, it must be greater than or equal to the vecsize declared in the shader,
// or behavior is undefined.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct MSLShaderInterfaceVariable {
    pub location: u32,
    pub component: u32,
    pub format: MSLShaderVariableFormat,
    pub builtin: BuiltIn,
    pub vecsize: u32,
    pub rate: MSLShaderVariableRate,
}

impl Default for MSLShaderInterfaceVariable {
    fn default() -> Self {
        MSLShaderInterfaceVariable {
            location: 0,
            component: 0,
            format: MSL_SHADER_VARIABLE_FORMAT_OTHER,
            builtin: BuiltInMax,
            vecsize: 0,
            rate: MSL_SHADER_VARIABLE_RATE_PER_VERTEX,
        }
    }
}

/// `MSLResourceBinding`: matches the binding index of a MSL resource for a
/// binding within a descriptor set.
// Taken together, the stage, desc_set and binding combine to form a reference to a resource
// descriptor used in a particular shading stage. The count field indicates the number of
// resources consumed by this binding, if the binding represents an array of resources.
// If the resource array is a run-time-sized array, which are legal in GLSL or SPIR-V, this value
// will be used to declare the array size in MSL, which does not support run-time-sized arrays.
// If pad_argument_buffer_resources is enabled, the base_type and count values are used to
// specify the base type and array size of the resource in the argument buffer, if that resource
// is not defined and used by the shader. With pad_argument_buffer_resources enabled, this
// information will be used to pad the argument buffer structure, in order to align that
// structure consistently for all uses, across all shaders, of the descriptor set represented
// by the arugment buffer. If pad_argument_buffer_resources is disabled, base_type does not
// need to be populated, and if the resource is also not a run-time sized array, the count
// field does not need to be populated.
// If using MSL 2.0 argument buffers, the descriptor set is not marked as a discrete descriptor set,
// and (for iOS only) the resource is not a storage image (sampled != 2), the binding reference we
// remap to will become an [[id(N)]] attribute within the "descriptor set" argument buffer structure.
// For resources which are bound in the "classic" MSL 1.0 way or discrete descriptors, the remap will
// become a [[buffer(N)]], [[texture(N)]] or [[sampler(N)]] depending on the resource types used.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct MSLResourceBinding {
    pub stage: ExecutionModel,
    pub basetype: BaseType,
    pub desc_set: u32,
    pub binding: u32,
    pub count: u32,
    pub msl_buffer: u32,
    pub msl_texture: u32,
    pub msl_sampler: u32,
}

impl Default for MSLResourceBinding {
    fn default() -> Self {
        MSLResourceBinding {
            stage: ExecutionModelMax,
            basetype: BaseType::Unknown,
            desc_set: 0,
            binding: 0,
            count: 0,
            msl_buffer: 0,
            msl_texture: 0,
            msl_sampler: 0,
        }
    }
}

