/// `MSLConstexprSampler`.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct MSLConstexprSampler {
    pub coord: MSLSamplerCoord,
    pub min_filter: MSLSamplerFilter,
    pub mag_filter: MSLSamplerFilter,
    pub mip_filter: MSLSamplerMipFilter,
    pub s_address: MSLSamplerAddress,
    pub t_address: MSLSamplerAddress,
    pub r_address: MSLSamplerAddress,
    pub compare_func: MSLSamplerCompareFunc,
    pub border_color: MSLSamplerBorderColor,
    pub lod_clamp_min: f32,
    pub lod_clamp_max: f32,
    pub max_anisotropy: i32,

    // Sampler Y'CbCr conversion parameters
    pub planes: u32,
    pub resolution: MSLFormatResolution,
    pub chroma_filter: MSLSamplerFilter,
    pub x_chroma_offset: MSLChromaLocation,
    pub y_chroma_offset: MSLChromaLocation,
    pub swizzle: [MSLComponentSwizzle; 4], // IDENTITY, IDENTITY, IDENTITY, IDENTITY
    pub ycbcr_model: MSLSamplerYCbCrModelConversion,
    pub ycbcr_range: MSLSamplerYCbCrRange,
    pub bpc: u32,

    pub compare_enable: bool,
    pub lod_clamp_enable: bool,
    pub anisotropy_enable: bool,
    pub ycbcr_conversion_enable: bool,
}

impl Default for MSLConstexprSampler {
    fn default() -> Self {
        MSLConstexprSampler {
            coord: MSL_SAMPLER_COORD_NORMALIZED,
            min_filter: MSL_SAMPLER_FILTER_NEAREST,
            mag_filter: MSL_SAMPLER_FILTER_NEAREST,
            mip_filter: MSL_SAMPLER_MIP_FILTER_NONE,
            s_address: MSL_SAMPLER_ADDRESS_CLAMP_TO_EDGE,
            t_address: MSL_SAMPLER_ADDRESS_CLAMP_TO_EDGE,
            r_address: MSL_SAMPLER_ADDRESS_CLAMP_TO_EDGE,
            compare_func: MSL_SAMPLER_COMPARE_FUNC_NEVER,
            border_color: MSL_SAMPLER_BORDER_COLOR_TRANSPARENT_BLACK,
            lod_clamp_min: 0.0,
            lod_clamp_max: 1000.0,
            max_anisotropy: 1,
            planes: 0,
            resolution: MSL_FORMAT_RESOLUTION_444,
            chroma_filter: MSL_SAMPLER_FILTER_NEAREST,
            x_chroma_offset: MSL_CHROMA_LOCATION_COSITED_EVEN,
            y_chroma_offset: MSL_CHROMA_LOCATION_COSITED_EVEN,
            swizzle: [MSL_COMPONENT_SWIZZLE_IDENTITY; 4],
            ycbcr_model: MSL_SAMPLER_YCBCR_MODEL_CONVERSION_RGB_IDENTITY,
            ycbcr_range: MSL_SAMPLER_YCBCR_RANGE_ITU_FULL,
            bpc: 8,
            compare_enable: false,
            lod_clamp_enable: false,
            anisotropy_enable: false,
            ycbcr_conversion_enable: false,
        }
    }
}

impl MSLConstexprSampler {
    pub fn swizzle_is_identity(&self) -> bool {
        self.swizzle[0] == MSL_COMPONENT_SWIZZLE_IDENTITY
            && self.swizzle[1] == MSL_COMPONENT_SWIZZLE_IDENTITY
            && self.swizzle[2] == MSL_COMPONENT_SWIZZLE_IDENTITY
            && self.swizzle[3] == MSL_COMPONENT_SWIZZLE_IDENTITY
    }

    pub fn swizzle_has_one_or_zero(&self) -> bool {
        self.swizzle
            .iter()
            .any(|&s| s == MSL_COMPONENT_SWIZZLE_ZERO || s == MSL_COMPONENT_SWIZZLE_ONE)
    }
}

// Special constant used in a MSLResourceBinding desc_set
