pub(crate) const SPVFuncImplSubgroupClusteredFMax: SPVFuncImpl = SPVFuncImplSubgroupClusteredMax;
pub(crate) const SPVFuncImplSubgroupClusteredSMax: SPVFuncImpl = SPVFuncImplSubgroupClusteredMax;
pub(crate) const SPVFuncImplSubgroupClusteredUMax: SPVFuncImpl = SPVFuncImplSubgroupClusteredMax;
