    // Returns the byte alignment of a type.
    pub(crate) fn get_declared_type_alignment_msl(
        &self,
        type_id: TypeID,
        special_type: Option<&SPIRType>,
        is_packed: bool,
        row_major: bool,
    ) -> Result<u32> {
        self.get_declared_type_alignment_msl_d(type_id, special_type, is_packed, row_major, 0)
    }

    fn get_declared_type_alignment_msl_d(
        &self,
        type_id: TypeID,
        special_type: Option<&SPIRType>,
        is_packed: bool,
        row_major: bool,
        depth: u32,
    ) -> Result<u32> {
        if depth > 1024 {
            spirv_cross_throw!("Type recursion too deep.");
        }
        let type_ = if type_id != 0 {
            self.get::<SPIRType>(type_id)?
        } else {
            match special_type {
                Some(t) => t,
                None => spirv_cross_throw!("No type given."),
            }
        };

        // Pointers align on multiples of 8 bytes.
        // Deliberately ignore array-ness here. It's not relevant for alignment.
        if type_.pointer && type_.storage == StorageClassPhysicalStorageBuffer {
            return Ok(8);
        }

        match type_.basetype {
            BaseType::Unknown
            | BaseType::Void
            | BaseType::AtomicCounter
            | BaseType::Image
            | BaseType::SampledImage
            | BaseType::Sampler => {
                spirv_cross_throw!("Querying alignment of opaque object.");
            }

            BaseType::Double => {
                spirv_cross_throw!("double types are not supported in buffers in MSL.");
            }

            BaseType::Struct => {
                // In MSL, a struct's alignment is equal to the maximum alignment of any of its members.
                let mut alignment: u32 = 1;
                for i in 0..type_.member_types.len() as u32 {
                    alignment = alignment.max(self.get_declared_struct_member_alignment_msl_d(
                        type_,
                        i,
                        depth + 1,
                    )?);
                }
                Ok(alignment)
            }

            _ => {
                if type_.basetype == BaseType::Int64
                    && !self.msl.options.supports_msl_version(2, 3, 0)
                {
                    spirv_cross_throw!(
                        "long types in buffers are only supported in MSL 2.3 and above."
                    );
                }
                if type_.basetype == BaseType::UInt64
                    && !self.msl.options.supports_msl_version(2, 3, 0)
                {
                    spirv_cross_throw!(
                        "ulong types in buffers are only supported in MSL 2.3 and above."
                    );
                }
                // Alignment of packed type is the same as the underlying component or column size.
                // Alignment of unpacked type is the same as the vector size.
                // Alignment of 3-elements vector is the same as 4-elements (including packed using column).
                if is_packed {
                    // If we have packed_T and friends, the alignment is always scalar.
                    Ok(type_.width / 8)
                } else {
                    // This is the general rule for MSL. Size == alignment.
                    let vecsize = if row_major && type_.columns > 1 {
                        type_.columns
                    } else {
                        type_.vecsize
                    };
                    Ok((type_.width / 8).wrapping_mul(if vecsize == 3 { 4 } else { vecsize }))
                }
            }
        }
    }

